-- GATE PACK 0258 table_privileges (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select c.relname as obj, r.role, coalesce(concat_ws(',', case when has_table_privilege(r.role, c.oid, 'SELECT') then 'select' end, case when has_table_privilege(r.role, c.oid, 'INSERT') then 'insert' end, case when has_table_privilege(r.role, c.oid, 'UPDATE') then 'update' end, case when has_table_privilege(r.role, c.oid, 'DELETE') then 'delete' end, case when has_table_privilege(r.role, c.oid, 'TRUNCATE') then 'truncate' end, case when has_table_privilege(r.role, c.oid, 'REFERENCES') then 'references' end, case when has_table_privilege(r.role, c.oid, 'TRIGGER') then 'trigger' end), '') as privs, c.relrowsecurity as rls
from pg_catalog.pg_class c
cross join (values ('anon'), ('authenticated'), ('service_role')) as r(role)
where c.oid in (pg_catalog.to_regclass('public.client_legal_identities'))
order by 1, 2;
